import struct, sys, os

TYPE_SIZES = {1:1,2:1,3:2,4:4,5:8,6:1,7:1,8:2,9:4,10:8,11:4,12:8}

def parse(path):
    data = open(path,'rb').read()
    bo = data[:2]
    if bo == b'II': endian='<'
    elif bo == b'MM': endian='>'
    else: raise ValueError('bad byte order '+repr(bo))
    magic = struct.unpack_from(endian+'H', data, 2)[0]
    ifd_off = struct.unpack_from(endian+'I', data, 4)[0]
    out = {'_endian':bo.decode(), '_magic':magic, '_size':len(data)}
    tagnames = {256:'ImageWidth',257:'ImageLength',258:'BitsPerSample',259:'Compression',
        262:'PhotometricInterpretation',277:'SamplesPerPixel',284:'PlanarConfiguration',
        322:'TileWidth',323:'TileLength',278:'RowsPerStrip',529:'YCbCrCoefficients',
        530:'YCbCrSubSampling',531:'YCbCrPositioning',532:'ReferenceBlackWhite'}
    seen = set()
    off = ifd_off
    while off != 0 and off in range(len(data)) and off not in seen:
        seen.add(off)
        n = struct.unpack_from(endian+'H', data, off)[0]
        entries=[]
        for i in range(n):
            p = off+2+i*12
            tag, typ, cnt = struct.unpack_from(endian+'HHI', data, p)
            raw = data[p+8:p+12]
            tsz = TYPE_SIZES.get(typ,1)
            total = tsz*cnt
            if total <= 4:
                valbytes = raw[:total]
            else:
                voff = struct.unpack_from(endian+'I', raw, 0)[0]
                valbytes = data[voff:voff+total]
            vals=[]
            if typ in (3,8):
                vals=list(struct.unpack(endian+('H' if typ==3 else 'h')*cnt, valbytes)) if len(valbytes)>=total else []
            elif typ in (4,9):
                vals=list(struct.unpack(endian+('I' if typ==4 else 'i')*cnt, valbytes)) if len(valbytes)>=total else []
            elif typ in (5,10):
                fmt = endian+('I' if typ==5 else 'i')
                vals=[]
                for j in range(cnt):
                    a,b = struct.unpack_from(fmt+fmt, valbytes, j*8)
                    vals.append((a,b,a/b if b else None))
            elif typ in (1,6,7):
                vals=list(valbytes)
            elif typ==2:
                vals=[valbytes.rstrip(b'\0')]
            elif typ==11:
                vals=list(struct.unpack(endian+'f'*cnt, valbytes))
            elif typ==12:
                vals=list(struct.unpack(endian+'d'*cnt, valbytes))
            entries.append((tag,typ,cnt,vals))
        for tag,typ,cnt,vals in entries:
            if tag in tagnames:
                out[tagnames[tag]] = {'tag':tag,'type':typ,'count':cnt,'values':vals}
        out['_alltags'] = [(e[0],e[1],e[2]) for e in entries]
        nxt = struct.unpack_from(endian+'I', data, off+2+n*12)[0]
        off = nxt
    return out

def fmt(tag, d):
    if tag not in d: return 'ABSENT'
    e=d[tag]; v=e['values']
    if tag in ('YCbCrCoefficients','ReferenceBlackWhite'):
        return 'count=%d [%s]'%(e['count'], ', '.join('%d/%d=%.6g'%(a,b,c) for a,b,c in v))
    return 'type=%d count=%d values=%s'%(e['type'],e['count'],v)

TAGS=['ImageWidth','ImageLength','BitsPerSample','Compression','PhotometricInterpretation',
'SamplesPerPixel','PlanarConfiguration','YCbCrCoefficients','YCbCrSubSampling','YCbCrPositioning',
'ReferenceBlackWhite','TileWidth','TileLength','RowsPerStrip']

if __name__=='__main__':
    for path in sys.argv[1:]:
        d=parse(path)
        print('==== %s (endian=%s magic=%d size=%d) ===='%(os.path.basename(path),d['_endian'],d['_magic'],d['_size']))
        for t in TAGS:
            print('  %-26s %s'%(t+':', fmt(t,d)))
        print('  ALL TAGS (tag,type,count):', d['_alltags'])
        print()
